data.default.conf:
server {
  listen 8080;
  server_name _;
  root /usr/share/nginx/html;
  location = /healthz { access_log off; return 200 'ok\n'; add_header Content-Type text/plain; }
  location = /readyz { access_log off; return 200 'ready\n'; add_header Content-Type text/plain; }
  location /ws { proxy_pass http://farm-gate.farm-staging-system.svc.cluster.local:8080; proxy_http_version 1.1; proxy_set_header Upgrade $http_upgrade; proxy_set_header Connection "upgrade"; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; proxy_read_timeout 3600s; }
  location /api/ { proxy_pass http://farm-gate.farm-staging-system.svc.cluster.local:8080; proxy_set_header Host $host; proxy_set_header X-Forwarded-Proto $scheme; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; }
  location / { try_files $uri $uri/ /index.html; }
}
